import osimport sysimport socketinb_dir = '/home/eric/FilesFromWindows' os.chdir(inb_dir)sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)server_address = ('0.0.0.0',6644)print('Starting listener on {}'.format(server_address))sock.bind(server_address)keep_listening = Truewhile keep_listening:    sock.listen(1)    print('waiting for a connection')    connection, client_address = sock.accept()    try:        print('connection from: {}'.format(client_address))        ld = [f for f in os.listdir(inb_dir)]        print('newly scanned ld :\n{}'.format(ld))        lwf = ''         for i in range(len(ld)-1, 0, -1):            if ld[i][:2] == 'WF':                lwf = ld[i]                break        print('After WF searching for lwf = {}  length = {}'.format(lwf,len(lwf)))        if len(lwf)>0:            cnt = int(lwf[2:])            print('cnt set to {}'.format(cnt))            cnt += 1            nfn = 'WF' + str(cnt)        else:            nfn = 'WF0'        kr = True # Keep Receiving        data = ''        while kr:            pd = connection.recv(12) # Partial data            if len(pd) == 0:                kr = False            else:                data = data + pd.decode()        wd = data.encode() # Write Data        fo = open(nfn,'wb')        fo.write(wd)        fo.close()    except ValueError as e:        print('Error Encountered:\n{}'.format(e))        a = input('Do you want to exit? ')        if a.upper()[0] == 'Y':            break    print('file {} created in FilesFromWindow direcotry'.format(nfn))    ans = input('Keep listening (y/n) ')    if ans.lower()[0] != 'y':        keep_listening = Falseprint('Clean exit from tpc listening prog!')